package com.secure.documentwallet;

import android.app.*;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.io.*;import java.util.concurrent.*;

public class SecureShareHubActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private LinearLayout list;
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}LinearLayout page=VaultPageUi.page(this);LinearLayout head=VaultPageUi.header(this,"Secure Share Hub","Controlled document sharing");head.addView(VaultPageUi.badge(this,"New"),new LinearLayout.LayoutParams(-2,Ui.dp(this,26)));page.addView(head);page.addView(VaultPageUi.notice(this,"↗","Choose A Protected Item","My Vault decrypts a temporary copy only after you confirm",Ui.SOFT,Ui.TEAL));page.addView(VaultPageUi.sectionHead(this,"Available To Share","Protected copies"));list=Ui.column(this);page.addView(list);page.addView(VaultPageUi.toggleRow(this,"↓","Allow Recipient Download","The receiving app may keep its own copy",false,null));setContentView(VaultPageUi.screen(this,page,"profile"));load();}
 private void load(){io.execute(()->{try{JSONArray docs=new VaultRepository(this).all();runOnUiThread(()->render(docs));}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could Not Open Secure Share"));}});}
 private void render(JSONArray docs){list.removeAllViews();if(docs.length()==0){list.addView(VaultPageUi.notice(this,"□","No Documents Yet","Scan or upload an item before sharing",Ui.SOFT,Ui.TEAL));return;}for(int i=docs.length()-1;i>=0;i--){JSONObject doc=docs.optJSONObject(i);if(doc==null)continue;LinearLayout row=VaultPageUi.iconRow(this,"share",doc.optString("title","Document"),doc.optString("category","Document")+" · Create protected copy");row.setOnClickListener(v->confirm(doc));VaultPageUi.addRow(list,row);}}
 private void confirm(JSONObject doc){new AlertDialog.Builder(this).setTitle("Share "+doc.optString("title","Document")+"?").setMessage("My Vault will decrypt a temporary PDF into its secure cache and open Android's share panel. The temporary vault copy is removed automatically later.").setNegativeButton("Cancel",null).setPositiveButton("Prepare Secure Copy",(d,w)->share(doc)).show();}
 private void share(JSONObject doc){ProgressDialog wait=new ProgressDialog(this);wait.setCancelable(false);wait.setMessage("Preparing Protected Copy…");wait.show();io.execute(()->{try{DocumentExporter exporter=new DocumentExporter(this);File file=exporter.pdf(doc,doc.optJSONArray("pages")!=null&&doc.optJSONArray("pages").length()==2);runOnUiThread(()->{wait.dismiss();VaultActivityLog.add(this,"Document Shared",doc.optString("title","Document"));exporter.share(file,"application/pdf");});}catch(Exception e){runOnUiThread(()->{wait.dismiss();Ui.toast(this,"Could Not Prepare This Document");});}});}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
